   281  static exr_result_t
   282  default_decompress_chunk (exr_decode_pipeline_t* decode)
   283  {
   284      exr_result_t rv = EXR_ERR_SUCCESS;
   285      EXR_PROMOTE_READ_CONST_CONTEXT_AND_PART_OR_ERROR (
   286          decode->context, decode->part_index);
   287
   288      if (part->storage_mode == EXR_STORAGE_DEEP_SCANLINE ||
   289          part->storage_mode == EXR_STORAGE_DEEP_TILED)
   290      {
   291          uint64_t sampsize =
   292              (((uint64_t) decode->chunk.width) *
   293               ((uint64_t) decode->chunk.height));
   294          sampsize *= sizeof (int32_t);
   295
   296          rv = decompress_data (
   297              pctxt,
   298              part->comp_type,
   299              decode,
   300              decode->packed_sample_count_table,
   301              decode->chunk.sample_count_table_size,
   302              decode->sample_count_table,
   303              sampsize);
   304
   305          if (rv != EXR_ERR_SUCCESS)
   306          {
   307              return pctxt->print_error (
   308                  pctxt,
   309                  rv,
   310                  "Unable to decompress sample table %" PRIu64 " -> %" PRIu64,
   311                  decode->chunk.sample_count_table_size,
   312                  (uint64_t) sampsize);
   313          }
   314          if ((decode->decode_flags & EXR_DECODE_SAMPLE_DATA_ONLY)) return rv;
   315      }
   316
   317      if (rv == EXR_ERR_SUCCESS)
   318          rv = decompress_data (
   319              pctxt,
   320              part->comp_type,
   321              decode,
   322              decode->packed_buffer,
   323              decode->chunk.packed_size,
   324              decode->unpacked_buffer,
   325              decode->chunk.unpacked_size);
   326
   327      if (rv != EXR_ERR_SUCCESS)
   328      {
   329          return pctxt->print_error (
   330              pctxt,
   331              rv,
   332              "Unable to decompress image data %" PRIu64 " -> %" PRIu64,
   333              decode->chunk.packed_size,
   334              decode->chunk.unpacked_size);
   335      }
   336      return rv;
   337  }
